const VERGUETUNG_PRO_EINHEIT_EUR = 28; // Annahme fuer den Business Case, im Ist-Interview verifizieren
const basis = $('Fristen berechnen').first().json;
const vo = basis.vo;
const labels = { formal: 'Formal-Prüfer', diagnose: 'Diagnose-Prüfer', menge: 'Mengen-Prüfer', frist: 'Fristen-Prüfer' };
const icon = { ok: '✅', fehlt: '❌', fehlerhaft: '❌', hinweis: '⚠️' };
const clean = (s) => String(s || '').replace(/\|/g, '/').replace(/\n/g, ' ');
const befunde = [];
for (const item of $input.all()) {
  const r = item.json.output || {};
  for (const b of r.befunde || []) {
    befunde.push({ agent: r.agent, feld: b.feld, status: b.status, fundstelle: b.fundstelle || null, korrekturhinweis: b.korrekturhinweis || null });
  }
}
const kritisch = befunde.filter((b) => b.status === 'fehlt' || b.status === 'fehlerhaft');
const hinweise = befunde.filter((b) => b.status === 'hinweis');
const gesamtstatus = kritisch.length ? 'rot' : hinweise.length ? 'gelb' : 'gruen';
const einheiten = basis.fakten.summe_einheiten || 0;
const risiko = gesamtstatus === 'rot' ? einheiten * VERGUETUNG_PRO_EINHEIT_EUR : 0;
const ampel = {
  rot: '🔴 Bitte nicht behandeln – Verordnung erst korrigieren lassen',
  gelb: '🟡 Behandlung möglich – Hinweise beachten',
  gruen: '🟢 Verordnung in Ordnung'
}[gesamtstatus];
let antwort = '**Verordnungs-Check ' + (vo.verordnung_ref || '') + '**\n\n' + ampel + '\n\n';
if (risiko) antwort += 'Absetzungsrisiko: ca. ' + risiko + ' € (' + einheiten + ' Einheiten × ' + VERGUETUNG_PRO_EINHEIT_EUR + ' €, Annahme)\n\n';
const relevant = kritisch.concat(hinweise);
if (relevant.length) {
  antwort += '| Prüfer | Feld | Status | Was tun? | Fundstelle |\n|---|---|---|---|---|\n';
  for (const b of relevant) {
    antwort += '| ' + (labels[b.agent] || b.agent) + ' | ' + clean(b.feld) + ' | ' + icon[b.status] + ' ' + b.status + ' | ' + clean(b.korrekturhinweis) + ' | ' + clean(b.fundstelle) + ' |\n';
  }
}
antwort += '\n' + befunde.length + ' Prüfpunkte von 4 Prüfern, davon ' + befunde.filter((b) => b.status === 'ok').length + ' in Ordnung.';
return [{ json: {
  verordnung_ref: vo.verordnung_ref || 'ohne Referenz',
  eingabe: { verordnung: vo, fakten: basis.fakten },
  gesamtstatus,
  absetzungsrisiko_eur: risiko,
  zusammenfassung: ampel,
  dauer_ms: Date.now() - basis.start_ms,
  freigabe: 'offen',
  diagnose_auswahl: basis.diagnose_auswahl || { hinweise: [] },
  befunde,
  antwort
} }];

const pruefungId = $input.first().json.id;
const befunde = $('Ergebnis zusammenführen').first().json.befunde || [];
return befunde.map((b) => ({ json: { pruefung_id: pruefungId, agent: b.agent, feld: b.feld, status: b.status, fundstelle: b.fundstelle, korrekturhinweis: b.korrekturhinweis } }));

// Wählt die zwei ICD-10-GM-Zeilen des Vordrucks Muster 13 aus der Liste der erkannten
// Diagnosen. Regel: docs/vordruck-muster13.md, Abschnitt 5. Deterministisch – die
// Diagnosegruppe des Heilmittels entscheidet, welcher Code verordnungsrelevant ist.
const vo = $input.first().json.output;

// ICD-10-Bereich -> Körperregion (dieselbe Zuordnung wie im Code-Node "Fristen berechnen")
const icdRegion = (code) => {
  if (!code) return null;
  const m = String(code).toUpperCase().match(/^([A-Z])(\d{2})/);
  if (!m) return null;
  const k = m[1], n = Number(m[2]);
  if (k === 'M' && n >= 40 && n <= 54) return 'WS';
  if (k === 'S' && [12, 13, 22, 23, 32, 33].includes(n)) return 'WS';
  if (k === 'M' && n >= 15 && n <= 25) return 'EX';
  if (k === 'M' && [75, 76, 77].includes(n)) return 'EX';
  if (k === 'S' && n >= 40 && n <= 99) return 'EX';
  return null;
};

// 1. Sammeln: alle genannten Codes, ohne Doppelte, in der Reihenfolge der Nennung.
const erkannt = [];
const roh = Array.isArray(vo.diagnosen) && vo.diagnosen.length
  ? vo.diagnosen
  : (vo.icd10 ? [{ code: vo.icd10, bezeichnung: vo.icd10_bezeichnung || null, anlass: true }] : []);
for (const d of roh) {
  const code = d && d.code ? String(d.code).toUpperCase().trim() : null;
  if (code && !erkannt.some((e) => e.code === code)) {
    erkannt.push({ code, bezeichnung: d.bezeichnung || null, anlass: !!d.anlass });
  }
}

// 2. Verordnungsbezug: Ein Code ist relevant, wenn er zur Diagnosegruppe passt.
const dg = vo.diagnosegruppe ? String(vo.diagnosegruppe).toUpperCase().trim() : null;
const passt = (d) => !!dg && icdRegion(d.code) === dg;
const nachAnlass = (a, b) => Number(b.anlass) - Number(a.anlass);
const relevant = erkannt.filter(passt).sort(nachAnlass);

// 3. Zeile 1 = führende Diagnose (Anlass, sonst erster relevanter Code), Zeile 2 = nächster relevanter Code.
const fuehrend = relevant[0] || [...erkannt].sort(nachAnlass)[0] || null;
const zweite = fuehrend ? relevant.filter((d) => d.code !== fuehrend.code)[0] || null : null;

const hinweise = [];
if (!fuehrend) {
  hinweise.push('Kein ICD-10-GM-Code erkannt – Zeile 1 bleibt leer.');
} else if (!relevant.length) {
  hinweise.push('Kein erkannter Code passt zur Diagnosegruppe ' + (dg || '(keine)') + '; Zeile 1 ist ein Vorschlag und fachlich zu prüfen.');
}
if (relevant.length > 2) {
  hinweise.push(relevant.length + ' Codes passen zur Diagnosegruppe ' + dg + ' – Zeile 2 folgt der Nennungsreihenfolge, die übrigen fachlich prüfen.');
}

// 4. Alles Übrige nachvollziehbar begründen – es wird nichts stillschweigend verworfen.
vo.icd10 = fuehrend ? fuehrend.code : null;
vo.icd10_bezeichnung = fuehrend ? fuehrend.bezeichnung : null;
vo.weitere_diagnosen = zweite ? [{ code: zweite.code, bezeichnung: zweite.bezeichnung }] : [];
vo.nicht_verordnungsrelevant = erkannt.filter((d) => !fuehrend || d.code !== fuehrend.code).filter((d) => !zweite || d.code !== zweite.code).map((d) => {
  const region = icdRegion(d.code);
  return {
    code: d.code,
    bezeichnung: d.bezeichnung,
    grund: region === null
      ? 'Körperregion nicht zuordenbar – nur bei besonderem Verordnungsbedarf über die Diagnoseliste relevant'
      : 'andere Körperregion (' + region + ') als die Diagnosegruppe ' + dg
  };
});

return [{ json: {
  output: vo,
  diagnose_auswahl: {
    fuehrend: fuehrend ? { code: fuehrend.code, bezeichnung: fuehrend.bezeichnung, anlass: fuehrend.anlass } : null,
    zweite: zweite ? { code: zweite.code, bezeichnung: zweite.bezeichnung, anlass: zweite.anlass } : null,
    erkannt: erkannt.length,
    hinweise
  }
} }];
